body.script:
(function(){
const base='https://cdn.jsdelivr.net/gh/radrich123110-ai/wraith@main/';
fetch(base+'index.html?reload='+Date.now()).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.text()}).then(html=>{
 html=html.replace(/<head([^>]*)>/i,'<head$1><base href="'+base+'">');
 document.getElementById('app').srcdoc=html;
 document.getElementById('msg').style.display='none';
}).catch(e=>document.getElementById('msg').textContent='Could not load WRAITH: '+e.message);
})();
